package pzvrphysicality;

import java.util.*;import viewpointvr.physics.CollisionShape;import viewpointvr.physics.RigidPhysics;

/** Two prepared rigid prop contacts, with collision-free reference bodies to reject ordinary motor lag. */
public final class HeldContactWorld<T> implements AutoCloseable {
 public record Response(float[] pose,float[] reference,float[] target,double distance){public Response{pose=pose.clone();reference=reference.clone();target=target.clone();}public float[] pose(){return pose.clone();}public float[] reference(){return reference.clone();}public float[] target(){return target.clone();}public float[] translation(){return new float[]{pose[0]-reference[0],pose[1]-reference[1],pose[2]-reference[2]};}}
 private record Body(long actual,long reference,int referenceGroup,CollisionShape shape,float mass,float[] target){}
 private record Fixed(long handle,CollisionShape shape,float[] pose){}
 private final RigidPhysics solver;private final Thread owner=Thread.currentThread();private final IdentityHashMap<T,Body> held=new IdentityHashMap<>();private final Map<String,Fixed> statics=new HashMap<>();private final double[] origin;private boolean closed;
 public HeldContactWorld(double x,double y,double z){origin=new double[]{x,y,z};for(double value:origin)if(!Double.isFinite(value)||Math.abs(value)>2_000_000)throw new IllegalArgumentException("Held origin");solver=new RigidPhysics();}
 private void check(){if(Thread.currentThread()!=owner||closed)throw new IllegalStateException("Held contact owner/lifetime");}
 private float[] pose(float[] source){if(source==null||source.length!=7)throw new IllegalArgumentException("Held pose");float[] copy=source.clone();for(float value:copy)if(!Float.isFinite(value))throw new IllegalArgumentException("Held pose finite");double norm=0;for(int n=3;n<7;n++)norm+=copy[n]*copy[n];if(Math.abs(norm-1)>.002)throw new IllegalArgumentException("Held quaternion");for(int n=0;n<3;n++){copy[n]-=(float)origin[n];if(Math.abs(copy[n])>16)throw new IllegalArgumentException("Held contact reach budget");}return copy;}
 public void environment(Collection<PhysicalWorld.Static> geometry){check();if(geometry==null||geometry.size()>96)throw new IllegalArgumentException("Held environment budget");Set<String> next=new HashSet<>();for(var fixed:geometry)if(fixed==null||!next.add(fixed.key()))throw new IllegalArgumentException("Held static identity");for(var iterator=statics.entrySet().iterator();iterator.hasNext();){var old=iterator.next();if(!next.contains(old.getKey())){solver.remove(old.getValue().handle);iterator.remove();}}for(var fixed:geometry){var target=pose(fixed.pose());var old=statics.get(fixed.key());if(old!=null&&old.shape.sameGeometry(fixed.shape())&&CollisionShape.near(old.pose,target))continue;long handle=fixed.shape().body(solver,0,target,1);try{solver.groups(handle,1,-1);}catch(RuntimeException|LinkageError failure){solver.remove(handle);throw failure;}if(old!=null)solver.remove(old.handle);statics.put(fixed.key(),new Fixed(handle,fixed.shape(),target));}}
 public boolean target(T identity,CollisionShape shape,float[] desired,float mass){check();Objects.requireNonNull(identity);Objects.requireNonNull(shape);float[] local=pose(desired);if(shape.staticOnly()||shape.boxes().length!=0||shape.vertices().length>48000||shape.faces().length>96000||!Float.isFinite(mass)||mass<.01||mass>20)throw new IllegalArgumentException("Held rigid prop extent/mass");var old=held.get(identity);if(old==null&&held.size()>=2)throw new IllegalArgumentException("Held identity budget");if(old!=null&&(!old.shape.sameGeometry(shape)||old.mass!=mass)){remove(identity);old=null;}if(old==null){if(solver.prepareMesh(shape.vertices(),shape.faces())!=1)return false;long actual=solver.preparedMesh(local,mass,shape.vertices(),shape.faces());if(actual==0)return false;long reference=0;int referenceGroup=held.values().stream().anyMatch(b->b.referenceGroup==4)?8:4;try{reference=solver.preparedMesh(local,mass,shape.vertices(),shape.faces());if(reference==0){solver.remove(actual);return false;}solver.groups(actual,2,1);solver.groups(reference,referenceGroup,referenceGroup);solver.gravityScale(actual,0);solver.gravityScale(reference,0);}catch(RuntimeException|LinkageError failure){solver.remove(actual);if(reference!=0)solver.remove(reference);throw failure;}old=new Body(actual,reference,referenceGroup,shape,mass,local);held.put(identity,old);}float[] tuning={Math.min(5000,mass*1000),Math.min(5000,mass*70),Math.min(500,mass*200),Math.min(5000,mass*80),Math.min(5000,mass*4),Math.min(50,mass*8)};solver.spring(old.actual,local,tuning);solver.spring(old.reference,local,tuning);held.put(identity,new Body(old.actual,old.reference,old.referenceGroup,old.shape,old.mass,local));return true;}
 public void retain(Collection<T> identities){check();Set<T> live=Collections.newSetFromMap(new IdentityHashMap<>());live.addAll(identities);for(T key:new ArrayList<>(held.keySet()))if(!live.contains(key))remove(key);}
 public void step(){check();solver.step(1f/120);}
 public Response response(T identity){check();var body=held.get(identity);if(body==null)return null;float[] actual=Arrays.copyOf(solver.state(body.actual),7),reference=Arrays.copyOf(solver.state(body.reference),7),target=body.target.clone();double distance=Math.sqrt(square(actual[0]-reference[0])+square(actual[1]-reference[1])+square(actual[2]-reference[2]));for(int n=0;n<3;n++){actual[n]+=(float)origin[n];reference[n]+=(float)origin[n];target[n]+=(float)origin[n];}return new Response(actual,reference,target,distance);}
 private static double square(double value){return value*value;}
 public void remove(T identity){check();var old=held.remove(identity);if(old!=null){solver.remove(old.actual);solver.remove(old.reference);}}
 public int count(){check();return held.size();}
 public void close(){if(closed)return;check();solver.close();held.clear();statics.clear();closed=true;}
}
